"""Resolve ROM trampoline slots against this exact stock RAM image, offline."""
from pathlib import Path
import json,struct,capstone,hashlib
P=Path('work/uv310-wireguard');blocks={int(k):bytes.fromhex(v) for k,v in json.loads((P/'private/wifi-rom-blocks.json').read_text()).items()};stock=(P/'private/web-assets/rtecdc_new.bin').read_bytes()
cs=capstone.Cs(capstone.CS_ARCH_ARM,capstone.CS_MODE_THUMB|capstone.CS_MODE_MCLASS);cs.detail=True
entries=[('bounded variadic strbuf formatter',0x802518),('add memory arena',0x806220),('main loop',0x806374),('timer object allocation candidate',0x806394),('aligned heap allocation',0x80640c),('clock accumulator candidate',0x806604),('timer queue insertion candidate',0x806620),('packet allocation',0x806d80),('packet accounting decrement candidate',0x806dd4),('SDPCM link wrapper',0x80a994),('SDPCM packet operation candidate',0x80aa54),('SDPCM ioctl unsupported default',0x80aa20),('Wi-Fi open/up candidate',0x80fb50),('Wi-Fi packet transmit candidate',0x80fc34),('Ethernet transmit path candidate',0x8281a4),('SDPCM send wrapper',0x804530)]
rows=[]
for label,a in entries:
 def read(a,n):return bytes(blocks[(a+i)&~63][(a+i)%64] for i in range(n))
 ins=list(cs.disasm(read(a,8),a));assert len(ins)==2
 assert ins[0].mnemonic=='mov.w' and ins[0].op_str.startswith('ip, #') and ins[1].mnemonic=='ldr.w'
 base=ins[0].operands[1].imm;delta=ins[1].operands[1].mem.disp;slot=base+delta;ptr=struct.unpack_from('<I',stock,slot)[0]
 rows.append({'role':label,'rom_entry':hex(a),'ram_dispatch_slot':hex(slot),'stock_image_dispatch_value':hex(ptr),'stock_target_kind':'ROM' if ptr>=0x800000 else 'RAM patch','live_dispatch_read':False,'abi_dynamic_validation':False})
e={'firmware_sha256':hashlib.sha256(stock).hexdigest(),'method':'Real captured ROM first two instructions + exact stock RAM-image word; runtime slot values have not been captured','entries':rows,'direct_calls_performed':False,'important':'ROM entry addresses are trampoline dispatchers; account for RAM patches before inferring actual behavior','packet_observations':{'wl_ops_slot_12':'0x80fc34 receives device pair and packet; references packet flags, calls 0x8281a4 on ordinary path; ownership/return semantics still require tracing','sdpcm_ops_slot_12':'0x80aa54 forwards through 0x804530; do not assume exact RX/TX semantics from table position','ethernet_tx_body':'0x8281ac checks 16-bit packet length at +0x14 >=14, reads data pointer +0x10 and EtherType bytes +12/+13; supports Ethernet frame interpretation. This does not prove packet ownership or hook suitability.', 'sdpcm_bridge_body':'0x804538 converts/accounts packet then routes via callback table; reverse path 0x8045b8 invokes destination dev->ops[3]. Exact live direction and framing remain to be validated.', 'packet_layout_candidates':{'0x10':'data pointer','0x14':'16-bit length','0x16':'flags'},'not_same_as_qdsp_host_packet':'Host driver previously used +0x18 length; these are different structures'},'wireguard_running':False}
e['heap_accounting']={'0x26c8': 'Total arena bytes: initialized at 0x1e608, incremented by add-arena 0x806250', '0x2688': 'Allocated payload accounting: incremented by malloc 0x806500, decremented by free 0x8062f4', '0x26a4': 'Allocated header accounting: +8 at 0x806506, -8 at 0x8062fc', '0x26cc': 'Peak allocated payload: conditional update at 0x806510', '0x2690': 'Allocation failure counter: increment at 0x806496 and 0x8064e4', '0x26c4': 'Free-list first-node pointer, node has payload size +0 and next +4', '0x806534': 'Default ROM implementation returns total arena - allocated payload; does not explicitly subtract allocated headers or free-list headers', 'live_values_measured': False, 'capacity_rule': 'Do not equate total arena or total-minus-payload with largest allocatable contiguous block. Need live bounded free-list traversal and stack high-water measurement.'}
Path('outputs/uv310-wireguard/evidence/rom-runtime-abi.json').write_text(json.dumps(e,indent=2)+'\n');print(json.dumps(e,indent=2))
